class Solution {
  public int uniquePaths(int[][] grid) {
    final int MOD = 1_000_000_007;
    int m = grid.length, n = grid[0].length;
    // land[d][i][j]: cell where the robot stands after entering (i, j) with direction d (0 right, 1
    // down)
    int[][][] land = new int[2][m + 1][n + 1];
    for (int d = 0; d < 2; d++) for (int[] row : land[d]) java.util.Arrays.fill(row, -1);
    for (int i = m - 1; i >= 0; i--) {
      for (int j = n - 1; j >= 0; j--) {
        for (int d = 0; d < 2; d++) {
          if (grid[i][j] == 0) land[d][i][j] = i * n + j;
          else if (d == 0) land[d][i][j] = i + 1 < m ? land[1][i + 1][j] : -1;
          else land[d][i][j] = j + 1 < n ? land[0][i][j + 1] : -1;
        }
      }
    }
    long[][] dp = new long[m][n];
    dp[0][0] = 1;
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (grid[i][j] == 1 || dp[i][j] == 0) continue;
        if (j + 1 < n && land[0][i][j + 1] >= 0) {
          int t = land[0][i][j + 1];
          dp[t / n][t % n] = (dp[t / n][t % n] + dp[i][j]) % MOD;
        }
        if (i + 1 < m && land[1][i + 1][j] >= 0) {
          int t = land[1][i + 1][j];
          dp[t / n][t % n] = (dp[t / n][t % n] + dp[i][j]) % MOD;
        }
      }
    }
    return (int) dp[m - 1][n - 1];
  }
}
